typedef enum { LIGHTS_OFF, POSITION, LOW_BEAM, COURTESY } LampState;
typedef struct { bool ignition_on; bool auto_mode; unsigned ambient_lux; bool welcome_request; bool battery_ok; unsigned courtesy_elapsed_ms; } Inputs;
typedef struct { bool position_lamps; bool low_beam; } Outputs;
void update_state(LampState *state, const Inputs *in) {
  switch (*state) {
    case LIGHTS_OFF:
      if (in->welcome_request && in->battery_ok) *state = COURTESY;
      else if (in->ignition_on && !in->auto_mode) *state = POSITION;
      else if (in->ignition_on && in->auto_mode && in->ambient_lux <= 40) *state = LOW_BEAM;
      break;
    case POSITION:
      if (!in->ignition_on) *state = LIGHTS_OFF;
      else if (in->auto_mode && in->ambient_lux <= 40) *state = LOW_BEAM;
      break;
    case LOW_BEAM:
      if (!in->ignition_on) *state = LIGHTS_OFF;
      else if (!in->auto_mode) *state = POSITION;
      else if (in->ambient_lux > 40) *state = LIGHTS_OFF;
      break;
    case COURTESY:
      if (!in->battery_ok || in->courtesy_elapsed_ms >= 30000) *state = LIGHTS_OFF;
      break;
  }
}
Outputs outputs_for(LampState state) {
  Outputs out = { false, false };
  if (state == POSITION) out.position_lamps = true;
  if (state == LOW_BEAM) { out.position_lamps = true; out.low_beam = true; }
  if (state == COURTESY) out.low_beam = true;
  return out;
}
